//! FreeANDIY branding: the paper-and-ink look, the UI font and the upstream attribution in About.
//!
//! The four themes stay (Settings ▸ Interface and saved settings are unchanged). Every theme gets
//! FreeANDIY's stamp-rose accent and flat print shape (nearly square windows, no soft shadows);
//! Paper becomes paper and ink, Midnight ink and paper. Charcoal and Silver keep upstream's
//! neutral greys: photos are judged against them.

use egui::{Color32, Context, Id, TextureHandle, TextureOptions, Ui, Visuals};

use crate::theme::{ThemeKind, Tokens};

pub const APP_NAME: &str = "{{this.name}}";
pub const OWNER: &str = "{{brand.owner}}";
pub const UPSTREAM_NAME: &str = "{{this.upstream_name}}";

const BLACK: Color32 = Color32::from_rgb({{rgb.black}});
const PAPER: Color32 = Color32::from_rgb({{rgb.paper}});
const WHITE: Color32 = Color32::from_rgb({{rgb.white}});
const ROSE: Color32 = Color32::from_rgb({{rgb.rose}});
const PINK: Color32 = Color32::from_rgb({{rgb.pink}});

/// `a` blended towards `b` by `t` (0..1), like ink at `t` opacity on paper.
const fn mix(a: Color32, b: Color32, t: f32) -> Color32 {
    Color32::from_rgb(channel(a.r(), b.r(), t), channel(a.g(), b.g(), t), channel(a.b(), b.b(), t))
}

const fn channel(x: u8, y: u8, t: f32) -> u8 {
    (x as f32 + (y as f32 - x as f32) * t + 0.5) as u8
}

/// The UI font. FreeANDIY Light keeps upstream's Inter: its panels and dialogs are laid out to
/// Inter's metrics, and IBM Plex Sans (taller lines, wider text, no ⌥) pushes fields and dialogs
/// out of view. The hook stays so the face can change in one place.
pub mod fonts {
    pub fn sans_regular() -> &'static [u8] {
        include_bytes!("../../../assets/fonts/Inter-Regular.ttf")
    }
    pub fn sans_semibold() -> &'static [u8] {
        include_bytes!("../../../assets/fonts/Inter-SemiBold.ttf")
    }
}

/// FreeANDIY's look on upstream's tokens for `kind`.
pub fn tokens(kind: ThemeKind, t: Tokens) -> Tokens {
    let t = Tokens { accent: if kind.is_dark() { PINK } else { ROSE }, ..t };
    match kind {
        ThemeKind::Paper => {
            let ink = |x: f32| mix(PAPER, BLACK, x);
            Tokens {
                chrome: PAPER,
                cell: ink(0.05),
                cell_selected: ink(0.14),
                divider: ink(0.18),
                inset: ink(0.05),
                field: WHITE,
                field_border: ink(0.30),
                button: ink(0.06),
                button_border: ink(0.35),
                hover: ink(0.09),
                pressed: ink(0.16),
                tool_active: ink(0.16),
                text: BLACK,
                text_label: ink(0.88),
                text_dim: ink(0.66),
                text_disabled: ink(0.42),
                icon: ink(0.80),
                ..t
            }
        }
        ThemeKind::Midnight => {
            let ink = |x: f32| mix(BLACK, PAPER, x);
            Tokens {
                chrome: BLACK,
                inset: mix(BLACK, Color32::BLACK, 0.25),
                field: mix(BLACK, Color32::BLACK, 0.30),
                field_border: ink(0.24),
                button: mix(BLACK, Color32::BLACK, 0.20),
                button_border: ink(0.30),
                hover: ink(0.12),
                pressed: ink(0.18),
                tool_active: ink(0.18),
                text: PAPER,
                text_label: ink(0.80),
                text_dim: ink(0.58),
                icon: ink(0.66),
                ..t
            }
        }
        _ => t,
    }
}

/// Flat print look for egui's own surfaces: nearly square windows and menus, no soft shadows.
pub fn visuals(v: &mut Visuals) {
    v.window_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.menu_corner_radius = egui::CornerRadius::same({{shape.radius_sm}});
    v.popup_shadow = egui::epaint::Shadow::NONE;
    v.window_shadow = egui::epaint::Shadow::NONE;
}

/// A constant (not a `tr` literal), so catalog-coverage reports don't ask upstream's languages
/// for it; the Slovak catalog translates it.
const ATTRIBUTION: &str = "{app} is based on the open-source project {upstream} (© ArtCraft Team and contributors, MIT/Apache-2.0). FreeANDIY is not affiliated with the ArtCraft team.";

const SEAL_PNG: &[u8] = include_bytes!("../../../freeandiy/assets/brand/fa-seal-rose.png");

fn seal(ctx: &Context) -> Option<TextureHandle> {
    let id = Id::new("freeandiy-seal");
    if let Some(tex) = ctx.data(|d| d.get_temp::<TextureHandle>(id)) {
        return Some(tex);
    }
    let img = lightcraft_codecs::decode_thumbnail(SEAL_PNG, 512).ok()?.image;
    let image = egui::ColorImage::from_rgba_unmultiplied([img.width, img.height], &img.as_bytes());
    let options = TextureOptions { mipmap_mode: Some(egui::TextureFilter::Linear), ..TextureOptions::LINEAR };
    let tex = ctx.load_texture("freeandiy-seal", image, options);
    ctx.data_mut(|d| d.insert_temp(id, tex.clone()));
    Some(tex)
}

/// The About tab's attribution: the Free Andy Agency seal and the upstream credit (MIT/Apache-2.0
/// require keeping the notices; the ArtCraft brand terms allow naming the origin in plain text).
pub fn about_attribution(ui: &mut Ui) {
    let t = Tokens::get(ui.ctx());
    ui.horizontal(|ui| {
        if let Some(tex) = seal(ui.ctx()) {
            ui.add(egui::Image::new(&tex).fit_to_exact_size(egui::vec2(56.0, 56.0)));
        }
        ui.vertical(|ui| {
            let text = crate::i18n::tr(ATTRIBUTION).replace("{app}", APP_NAME).replace("{upstream}", UPSTREAM_NAME);
            ui.label(egui::RichText::new(text).color(t.text_dim));
            ui.label(egui::RichText::new(format!("© {OWNER}")).color(t.text_dim));
        });
    });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_seal_decodes() {
        assert!(seal(&Context::default()).is_some());
    }

    #[test]
    fn paper_and_midnight_are_paper_and_ink() {
        let paper = Tokens::for_kind(ThemeKind::Paper);
        assert_eq!((paper.chrome, paper.text, paper.accent), (PAPER, BLACK, ROSE));
        let midnight = Tokens::for_kind(ThemeKind::Midnight);
        assert_eq!((midnight.chrome, midnight.text, midnight.accent), (BLACK, PAPER, PINK));
    }
}
